      "content": "rules_version = '2';\nservice cloud.firestore {\n  match /databases/{database}/documents {\n    match /v0/{d} {\n      allow read: if debug(null) != 0 || true;\n    }\n    match /v1/{d} {\n      allow read: if debug(true) != 0 || true;\n    }\n    match /v2/{d} {\n      allow read: if debug(2) != 0 || true;\n    }\n    match /v3/{d} {\n      allow read: if debug(-9223372036854775807 - 1) != 0 || true;\n    }\n    match /v4/{d} {\n      allow read: if debug(1.5) != 0 || true;\n    }\n    match /v5/{d} {\n      allow read: if debug(100000000.0) != 0 || true;\n    }\n    match /v6/{d} {\n      allow read: if debug(-0.0) != 0 || true;\n    }\n    match /v7/{d} {\n      allow read: if debug(0.001) != 0 || true;\n    }\n    match /v8/{d} {\n      allow read: if debug(0.0001) != 0 || true;\n    }\n    match /v9/{d} {\n      allow read: if debug(float('NaN')) != 0 || true;\n    }\n    match /v10/{d} {\n      allow read: if debug(float('Infinity')) != 0 || true;\n    }\n    match /v11/{d} {\n      allow read: if debug(-float('Infinity')) != 0 || true;\n    }\n    match /v12/{d} {\n      allow read: if debug('a\"b\\'c\\nd\\te') != 0 || true;\n    }\n    match /v13/{d} {\n      allow read: if debug('é😀\\u0001') != 0 || true;\n    }\n    match /v14/{d} {\n      allow read: if debug('') != 0 || true;\n    }\n    match /v15/{d} {\n      allow read: if debug(b'\\x00\\xffa') != 0 || true;\n    }\n    match /v16/{d} {\n      allow read: if debug('é'.toUtf8()) != 0 || true;\n    }\n    match /v17/{d} {\n      allow read: if debug([1, 'a', [2]]) != 0 || true;\n    }\n    match /v18/{d} {\n      allow read: if debug([]) != 0 || true;\n    }\n    match /v19/{d} {\n      allow read: if debug({'b': 1, 'a': {'c': true}, 'é': 2, 'B': 3}) != 0 || true;\n    }\n    match /v20/{d} {\n      allow read: if debug({}) != 0 || true;\n    }\n    match /v21/{d} {\n      allow read: if debug([1, 2, 1.0].toSet()) != 0 || true;\n    }\n    match /v22/{d} {\n      allow read: if debug([].toSet()) != 0 || true;\n    }\n    match /v23/{d} {\n      allow read: if debug({'c': 1, 'a': 2, 'b': 3}.diff({'b': 1, 'a': 2, 'd': 4})) != 0 || true;\n    }\n    match /v24/{d} {\n      allow read: if debug(timestamp.value(0)) != 0 || true;\n    }\n    match /v25/{d} {\n      allow read: if debug(timestamp.value(1500)) != 0 || true;\n    }\n    match /v26/{d} {\n      allow read: if debug(timestamp.date(2020, 1, 2)) != 0 || true;\n    }\n    match /v27/{d} {\n      allow read: if debug(duration.value(90, 's')) != 0 || true;\n    }\n    match /v28/{d} {\n      allow read: if debug(duration.value(-1500, 'ms')) != 0 || true;\n    }\n    match /v29/{d} {\n      allow read: if debug(duration.time(1, 2, 3, 4)) != 0 || true;\n    }\n    match /v30/{d} {\n      allow read: if debug(duration.value(0, 's')) != 0 || true;\n    }\n    match /v31/{d} {\n      allow read: if debug(latlng.value(1.5, -2.25)) != 0 || true;\n    }\n    match /v32/{d} {\n      allow read: if debug(latlng.value(0, 0)) != 0 || true;\n    }\n    match /v33/{d} {\n      allow read: if debug(latlng.value(-0.0, 0.00001)) != 0 || true;\n    }\n    match /v34/{d} {\n      allow read: if debug(path('a/b%20c')) != 0 || true;\n    }\n    match /v35/{d} {\n      allow read: if debug(/databases/$(database)/documents/v/$(d)) != 0 || true;\n    }\n    match /v36/{d} {\n      allow read: if debug(d) != 0 || true;\n    }\n    match /v37/{d} {\n      allow read: if debug(int(d + '1')) != 0 || true;\n    }\n    match /v38/{d} {\n      allow read: if debug(float('1.0E10')) != 0 || true;\n    }\n  }\n}\n",
      "name": "firestore.rules"
    }]
