rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    function t() {
      return request.auth.token;
    }
    function f2() {
      let z = int('q');
      return z == 1;
    }
    function f3(x) {
      return x.size() == 1;
    }
    match /e0/{d} {
      allow read: if (t().n + t().s == 2) || true;
    }
    match /e1/{d} {
      allow read: if (t().l[5] == 1) || true;
    }
    match /e2/{d} {
      allow read: if (request.x == 1) || true;
    }
    match /e3/{d} {
      allow read: if (t().n.size() == 1) || true;
    }
    match /e4/{d} {
      allow read: if (-t().s == 1) || true;
    }
    match /e5/{d} {
      allow read: if (!t().n) || true;
    }
    match /e6/{d} {
      allow read: if (t().m['b'] == 1) || true;
    }
    match /e7/{d} {
      allow read: if (t().m.b == 1) || true;
    }
    match /e8/{d} {
      allow read: if (t().s[1:10] == 'b') || true;
    }
    match /e9/{d} {
      allow read: if (f2()) || true;
    }
    match /e10/{d} {
      allow read: if ((true ? int('x') : 1) == 1) || true;
    }
    match /e11/{d} {
      allow read: if (1 in t().n) || true;
